namespace RonSijm.FluidHumidifier.Factories.BedrockAgentCore;

public class InnerMemoryMemoryStrategyFactory(Action<Humidifier.BedrockAgentCore.MemoryTypes.MemoryStrategy> factoryAction = null) : SubResourceFactory<Humidifier.BedrockAgentCore.MemoryTypes.MemoryStrategy>
{

    internal InnerMemorySummaryMemoryStrategyFactory SummaryMemoryStrategyFactory { get; set; }

    internal InnerMemoryCustomMemoryStrategyFactory CustomMemoryStrategyFactory { get; set; }

    internal InnerMemorySemanticMemoryStrategyFactory SemanticMemoryStrategyFactory { get; set; }

    internal InnerMemoryUserPreferenceMemoryStrategyFactory UserPreferenceMemoryStrategyFactory { get; set; }

    internal InnerMemoryEpisodicMemoryStrategyFactory EpisodicMemoryStrategyFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.MemoryTypes.MemoryStrategy Create()
    {
        var memoryStrategyResult = CreateMemoryStrategy();
        factoryAction?.Invoke(memoryStrategyResult);

        return memoryStrategyResult;
    }

    private Humidifier.BedrockAgentCore.MemoryTypes.MemoryStrategy CreateMemoryStrategy()
    {
        var memoryStrategyResult = new Humidifier.BedrockAgentCore.MemoryTypes.MemoryStrategy();

        return memoryStrategyResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.MemoryTypes.MemoryStrategy result)
    {
        base.CreateChildren(result);

        result.SummaryMemoryStrategy ??= SummaryMemoryStrategyFactory?.Build();
        result.CustomMemoryStrategy ??= CustomMemoryStrategyFactory?.Build();
        result.SemanticMemoryStrategy ??= SemanticMemoryStrategyFactory?.Build();
        result.UserPreferenceMemoryStrategy ??= UserPreferenceMemoryStrategyFactory?.Build();
        result.EpisodicMemoryStrategy ??= EpisodicMemoryStrategyFactory?.Build();
    }

} // End Of Class

